<script lang="ts">
  import {onMount} from 'svelte';
  import NativeInteractionControl from './NativeInteractionControl.svelte';
  import {t,locale,formatDate,formatNumber} from '../lib/i18n';
  import {call,native,onEvent} from '../lib/api';
  import {parseExperience,parsePreferences,parseInteraction,factualRecap,presetLabels,factLabels,phaseLabels,experienceError,type ExperienceSnapshot,type ExperiencePreferences,type InteractionKind} from '../lib/experience';
  interface Props {botId:string;bots:{id:string;name:string}[];active:boolean;disabled?:boolean;onDirtyChange?:(dirty:boolean)=>void;onBusyChange?:(busy:boolean)=>void}
  let {botId,bots,active,disabled=false,onDirtyChange,onBusyChange}:Props=$props();
  let snapshot=$state<ExperienceSnapshot>(),draft=$state<ExperiencePreferences>(),pending=$state(false),preferenceWrite=$state(false),error=$state(''),feedback=$state(''),publicOnly=$state(false),confirmDelete=$state(false);
  let alive=false,epoch=0;
  const uid=$props.id();
  const dirty=$derived(!!draft&&!!snapshot&&JSON.stringify(draft)!==JSON.stringify(snapshot.settings.preferences));
  $effect(()=>{onDirtyChange?.(dirty);});$effect(()=>{onBusyChange?.(preferenceWrite);});
  export async function saveDraft(){await save();}
  export function discardDraft(){if(snapshot)draft=structuredClone(snapshot.settings.preferences);}
  const recap=$derived(factualRecap(snapshot?.facts??[],publicOnly));
  const facts=$derived((snapshot?.facts??[]).filter(f=>!publicOnly||f.shared));
  const latest=$derived(facts[0]);
  function accept(value:unknown,id:string){const next=parseExperience(value,id);snapshot=next;draft=structuredClone(next.settings.preferences);}
  async function refresh(){const id=botId,token=++epoch;try{const value=await call('get_experience_snapshot',{botId:id});if(alive&&token===epoch&&id===botId){accept(value,id);error='';}}catch(e){if(alive&&token===epoch){snapshot=undefined;draft=undefined;error=experienceError(e);}}}
  $effect(()=>{botId;if(alive){snapshot=undefined;draft=undefined;feedback='';confirmDelete=false;void refresh();}});
  async function mutate(command:string,args:Record<string,unknown>){if(pending||disabled)return;const id=botId,token=++epoch;pending=true;preferenceWrite=true;error='';try{const result=await call(command,{botId:id,...args});if(alive&&id===botId&&token===epoch)accept(result,id);}catch(e){if(alive&&id===botId)error=experienceError(e);}finally{if(alive){pending=false;preferenceWrite=false;}}}
  async function save(){if(!snapshot||!draft)return;try{const preferences=parsePreferences(draft);await mutate('set_experience_preferences',{expectedRevision:snapshot.settings.revision,preferences});}catch(e){error=experienceError(e);}}
  async function interact(kind:InteractionKind){if(pending||disabled||!active)return;const id=botId,token=++epoch;pending=true;feedback='';error='';try{const result=parseInteraction(await call('request_character_interaction',{botId:id,request:{kind,targetActorId:null}}),id,kind);if(alive&&id===botId&&token===epoch){feedback=result.status==='accepted'?'Aktion angenommen. Die Ausführung wird separat bestätigt.':result.status==='waiting'?'Die Figur wartet.':result.status==='declined'?'Die Figur hat die Anfrage abgelehnt.':'Die Aktion wurde abgebrochen.';}}catch(e){if(alive&&id===botId)error=experienceError(e);}finally{if(alive)pending=false;}if(alive&&id===botId)void refresh();}
  async function editFact(eventId:string|null,shared?:boolean){if(pending||disabled)return;const id=botId;pending=true;try{await call(shared===undefined?'delete_experience_fact':'set_experience_fact_shared',{botId:id,eventId, ...(shared===undefined?{}:{shared})});if(alive&&id===botId){confirmDelete=false;await refresh();}}catch(e){if(alive&&id===botId)error=experienceError(e);}finally{if(alive)pending=false;}}
  function participant(id:string,checked:boolean){if(!draft)return;draft={...draft,impulseParticipants:checked?[...draft.impulseParticipants,id]:draft.impulseParticipants.filter(v=>v!==id)};}
  onMount(()=>{alive=true;void refresh();let stop=()=>{};void onEvent('experience-state',value=>{if(value?.botId===botId&&!dirty&&!pending){try{accept(value,botId);}catch{error='Die Aktivitätsdaten sind ungültig.';}}}).then(fn=>{if(alive)stop=fn;else fn();});return()=>{alive=false;++epoch;onDirtyChange?.(false);onBusyChange?.(false);stop();};});
</script>
<section class="experience settings-panel" aria-labelledby={`${uid}-heading`}>
  <header><div><p class="eyebrow">{$t('Alltag deiner Figuren')}</p><h2 id={`${uid}-heading`}>{$t('Absicht & Aktivität')}</h2></div><button class="text-link" disabled={pending||dirty||disabled} onclick={refresh}>{$t('Neu laden')}</button></header>
  {#if error}<p class="error" role="alert">{$t(error)}</p>{/if}
  {#if snapshot&&draft}
    <div class="intent" aria-live="polite"><span class:live={active&&!snapshot.paused} class="signal"></span><div><strong>{snapshot.paused?$t('Zentral pausiert'):active?$t('Life läuft'):$t('Life ist gestoppt')}</strong>{#if draft.intentVisible&&latest}<p>{$t(factLabels[latest.kind])} · {$t(phaseLabels[latest.phase])} · {latest.actorIds.map(id=>bots.find(b=>b.id===id)?.name??$t('Entfernte Figur')).join(', ')}</p>{:else}<p>{$t('Bestätigte Aktivitäten erscheinen hier. Leere Zeit wird nicht als Erlebnis erfunden.')}</p>{/if}</div><button class="button secondary" disabled={!active||pending||disabled} onclick={()=>mutate('set_experience_pause',{paused:!snapshot!.paused})}>{$t(snapshot.paused?'Aktivitäten fortsetzen':'Zentral pausieren')}</button></div>
    <fieldset disabled={pending||disabled}><legend>{$t('Alltagsmodus')}</legend><div class="presets">{#each Object.entries(presetLabels) as [preset,label]}<label class:selected={draft.preset===preset}><input type="radio" name={`${uid}-preset`} value={preset} checked={draft.preset===preset} onchange={()=>draft&&(draft={...draft,preset:preset as ExperiencePreferences['preset']})}/><span>{$t(label)}</span></label>{/each}</div><p class="note">{$t(draft.preset==='quiet'?'Keine unaufgeforderte Sprache oder Texte.':draft.preset==='focus'?'Leise Selbstpflege mit weniger Initiativen.':'Sichtbare Szenen nur mit deiner Freigabe. Private Erinnerungen bleiben privat.')}</p>
      <div class="limits"><label>{$t('Lautstärke')}<input type="range" min="0" max="100" step="1" bind:value={draft.volume}/><output>{formatNumber(draft.volume,$locale)}%</output></label><label>{$t('Pause zwischen Initiativen')}<select bind:value={draft.initiativeCooldownMs}><option value={5000}>{$t('5 Sekunden')}</option><option value={30000}>{$t('30 Sekunden')}</option><option value={60000}>{$t('1 Minute')}</option><option value={300000}>{$t('5 Minuten')}</option>{#if ![5000,30000,60000,300000].includes(draft.initiativeCooldownMs)}<option value={draft.initiativeCooldownMs}>{formatNumber(draft.initiativeCooldownMs/1000,$locale)} s</option>{/if}</select></label><label>{$t('Bewegungsradius')}<input type="range" min="0" max="1000" step="10" bind:value={draft.movementRadius}/><output>{formatNumber(draft.movementRadius/10,$locale)}%</output></label></div>
      <label class="check"><input type="checkbox" bind:checked={draft.intentVisible}/>{$t('Aktuelle Absicht anzeigen')}</label>
      <details><summary>{$t('Erlaubte Animationen')}</summary><div class="animation-list">{#each ['idle','walk','wave','play','rest','pet','jump','sit'] as motion}<label class="check"><input type="checkbox" checked={draft.allowedAnimations.includes(motion)} onchange={e=>draft&&(draft={...draft,allowedAnimations:e.currentTarget.checked?[...draft.allowedAnimations,motion]:draft.allowedAnimations.filter(v=>v!==motion)})}/>{$t(({idle:'Stillstehen',walk:'Laufen',wave:'Winken',play:'Spielen',rest:'Ruhen',pet:'Streicheln',jump:'Springen',sit:'Sitzen'} as Record<string,string>)[motion])}</label>{/each}</div><p class="note">{$t('Eine Freigabe ersetzt keine Modellfähigkeit. Fehlende Animationen erhalten einen sicheren Ersatz.')}</p></details>
      <details><summary>{$t('Impulse aus Twitch & YouTube')}</summary><p class="note">{$t('Nur native, zugeordnete Ereignisse dürfen geschlossene Spiel-, Gruß- oder Abstimmungsimpulse vorschlagen. Chattexte ändern keine Rechte und starten Life nicht.')}</p><p class="note">{$t('Wartend')}: {formatNumber(snapshot.impulses.queued,$locale)} · {$t('Angenommen')}: {formatNumber(snapshot.impulses.accepted,$locale)} · {$t('Verworfen')}: {formatNumber(snapshot.impulses.dropped,$locale)}</p><label class="check"><input type="checkbox" bind:checked={draft.streamImpulses}/>{$t('Stream-Impulse ausdrücklich erlauben')}</label><div class="animation-list">{#each bots as bot}<label class="check"><input type="checkbox" checked={draft.impulseParticipants.includes(bot.id)} disabled={!draft.impulseParticipants.includes(bot.id)&&draft.impulseParticipants.length>=8} onchange={e=>participant(bot.id,e.currentTarget.checked)}/>{bot.name}</label>{/each}</div><p class="note">{$t('Nur im Stream-Modus: höchstens 16 wartende Impulse, 30 Sekunden Lebensdauer und die eingestellte Pause pro Figur. Fokus, Pause und Stop verwerfen wartende Impulse.')}</p></details>
      <details><summary>{$t('Optionale Desktop-Anker')}</summary><p class="note">{$t('Fensterkanten und Cursor benötigen eine eigene geprüfte Geometriequelle. Bildschirmaufnahme und Eingaberechte werden dadurch nicht freigegeben.')}</p><label class="check"><input type="checkbox" bind:checked={draft.desktopAnchors} disabled={!snapshot.desktopCapabilities.externalWindows&&!draft.desktopAnchors}/>{$t('An geprüften Fensterkanten sitzen')}</label><label class="check"><input type="checkbox" bind:checked={draft.cursorPlay} disabled={!snapshot.desktopCapabilities.cursor&&!draft.cursorPlay}/>{$t('Begrenztes Cursor-Spiel erlauben')}</label>{#if snapshot.desktopCapabilities.reason==='native_provider'}<p class="note">{$t('macOS unterstützt eine rein geometrische Quelle. Sie wird nur bei eigener Freigabe während einer geprüften Life-Sitzung gelesen; bei Verlust gelten feste Plätze.')}</p>{/if}{#if !snapshot.desktopCapabilities.externalWindows||!snapshot.desktopCapabilities.cursor}<p class="note">{$t('Auf dieser Plattform ist noch keine geprüfte Quelle verfügbar. Nutze die festen Plätze im visuellen Editor.')}</p>{/if}</details>
    </fieldset>
    <footer><p class="note">{$t('Gespeichert werden Vorlieben, niemals ein laufender Life-Start.')}</p><button class="button primary" disabled={!dirty||pending||disabled} onclick={save}>{$t('Alltagseinstellungen speichern')}</button></footer>
    <div class="direct"><h3>{$t('Direkt mit der Figur interagieren')}</h3><p class="note">{$t('Anfragen laufen durch dieselben Belegt-, Ruhe- und Abbruchregeln wie andere Aktionen.')}</p><div class="buttons">{#each [['pet','Streicheln'],['play','Zum Spielen einladen'],['home','Zum Ruheplatz schicken'],['pause','Pause anfordern']] as [kind,label]}<button class="button secondary" disabled={!native||!active||pending||disabled} onclick={()=>interact(kind as InteractionKind)}>{$t(label)}</button>{/each}</div>{#if feedback}<p role="status">{$t(feedback)}</p>{/if}<NativeInteractionControl {botId} {active} disabled={disabled||pending||dirty}/></div>
    <div class="recap"><header><h3>{$t('Faktisches Tagesalbum')}</h3><label class="check"><input type="checkbox" bind:checked={publicOnly}/>{$t('Öffentliche Vorschau')}</label></header><p class="note">{$t('Nur abgeschlossene, native Ereignisse. Lokal, höchstens 256 Einträge pro Figur und 30 Tage beim nächsten Ereignis. Keine Modellanfrage.')}</p>{#if !recap.length}<p class="empty">{$t('Noch keine bestätigten abgeschlossenen Aktivitäten.')}</p>{:else}<ul class="recap-list">{#each recap.slice(0,20) as group}<li><time>{formatDate(group.day*86400000,{dateStyle:'medium',timeZone:'UTC'},$locale)}</time><strong>{$t(factLabels[group.kind])}</strong><span>×{formatNumber(group.count,$locale)}</span></li>{/each}</ul>{/if}<details><summary>{$t('Ereignisse ansehen und verwalten')}</summary><ul class="facts">{#each facts.slice(0,40) as fact(fact.id)}<li><div><strong>{$t(factLabels[fact.kind])}</strong> · {$t(phaseLabels[fact.phase])}<small>{formatDate(fact.atMs,{dateStyle:'short',timeStyle:'short'},$locale)}</small></div>{#if fact.phase==='completed'}<label class="check"><input type="checkbox" checked={fact.shared} disabled={pending||disabled} onchange={e=>editFact(fact.id,e.currentTarget.checked)}/>{$t('Explizit öffentlich teilen')}</label>{/if}<button class="text-link" disabled={pending||disabled} onclick={()=>editFact(fact.id)}>{$t('Löschen')}</button></li>{/each}</ul>{#if confirmDelete}<p>{$t('Alle lokalen Aktivitätsfakten dieser Figur löschen?')}</p><button class="button secondary" disabled={pending||disabled} onclick={()=>editFact(null)}>{$t('Alle Fakten löschen')}</button><button class="text-link" onclick={()=>confirmDelete=false}>{$t('Abbrechen')}</button>{:else}<button class="text-link" disabled={!facts.length||pending||disabled} onclick={()=>confirmDelete=true}>{$t('Alle Fakten löschen')}</button>{/if}</details></div>
  {:else if !error}<p class="note">{$t('Aktivitäten werden geladen …')}</p>{/if}
</section>
<style>
.experience{margin-top:24px}.experience header,.experience footer{display:flex;justify-content:space-between;align-items:center;gap:16px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);margin:0 0 5px}.experience h2{margin:0;font-size:20px}.experience h3{font-size:14px}.intent{display:flex;gap:12px;align-items:center;margin:22px 0;padding:16px 0;border-block:1px solid var(--line)}.intent>div{flex:1}.intent p,.note{font-size:12px;line-height:1.7;color:var(--muted);margin:6px 0}.signal{width:8px;height:8px;border-radius:50%;background:var(--muted);flex-shrink:0}.signal.live{background:var(--accent)}fieldset{border:0;margin:0;padding:0}legend{font-size:12px;font-weight:600;margin-bottom:10px}.presets{display:flex;gap:6px}.presets label{display:flex;gap:8px;align-items:center;padding:9px 16px;border:1px solid var(--line);border-radius:8px;font-size:13px;cursor:pointer}.presets .selected{border-color:var(--accent)}.presets input{width:auto}.limits{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:20px 0}.limits label{display:grid;gap:8px;font-size:12px}.limits output{color:var(--muted)}input[type=range]{padding:0;accent-color:var(--accent)}.check{display:flex;align-items:center;gap:8px;font-size:12px;margin:10px 0}.check input{width:auto;accent-color:var(--accent)}details{border-top:1px solid var(--line);padding:14px 0}summary{font-size:12px;cursor:pointer}.animation-list,.buttons{display:flex;gap:8px 16px;flex-wrap:wrap}.direct,.recap{margin-top:24px;border-top:1px solid var(--line);padding-top:14px}.recap-list,.facts{list-style:none;padding:0}.recap-list li{display:grid;grid-template-columns:130px 1fr auto;gap:12px;padding:10px 0;border-bottom:1px solid var(--line);font-size:12px}.recap-list time{color:var(--muted)}.facts li{padding:14px 0;border-bottom:1px solid var(--line);font-size:12px}.facts small{display:block;color:var(--muted);margin-top:5px}.error{color:var(--danger);font-size:12px}.empty{font-size:13px;color:var(--muted);padding:20px 0}@media(max-width:720px){.limits{grid-template-columns:1fr}.intent{flex-wrap:wrap}.intent>button{width:100%}.experience footer{align-items:start;flex-direction:column}.presets label{padding:8px 10px}.recap-list li{grid-template-columns:100px 1fr auto}}
</style>
